from collections import Counter
from fractions import Fraction
import json
from pathlib import Path

from vs import corpus, dsl, ivtff, path

WORK = Path(__file__).resolve().parent
SPEC = json.loads((WORK / "fact-spec.json").read_text())
WITH_NULL = {**SPEC, "compare": [
    {"null": "shuffle_within_line", "direction": "greater", "p": .01, "perms": 199}
]}


def load(transliteration, mode):
    training, practice = corpus.split_pages("practice", transliteration)
    if mode == "split":
        return training, practice
    joined = {page.id: page for page in ivtff.parse(
        path("data", "raw", corpus.TRANSLITERATIONS[transliteration]), uncertain_space="join"
    )}
    return [joined[p.id] for p in training], [joined[p.id] for p in practice]


def exact_null(eval_tokens, classes):
    hits = Fraction(0)
    pairs = 0
    for run in dsl.runs_of([token for token in eval_tokens if dsl._boundary_eligible(token)]):
        if len(run) < 2:
            continue
        states = []
        for token in run:
            glyphs = dsl._boundary_seg(token["w"])
            states.append((classes.get(glyphs[0]) == "start", classes.get(glyphs[-1]) == "end"))
        ending = sum(b for a, b in states)
        starting = sum(a for a, b in states)
        both = sum(a and b for a, b in states)
        hits += Fraction(ending * starting - both, len(run))
        pairs += len(run) - 1
    return float(hits / pairs), pairs


def main():
    report = {}
    for trans in corpus.EVA_TRANSLITERATIONS:
        for mode in ("split", "join"):
            training, practice = load(trans, mode)
            official = dsl.evaluate(SPEC, practice, training)
            classes = dsl._boundary_classes(dsl.tokens(training))
            expected, pairs = exact_null(dsl.tokens(practice), classes)
            assert official["detail"]["boundary_class_rate"]["pairs"] == pairs
            try:
                direction = dsl.evaluate(WITH_NULL, practice, training)["detail"]["shuffle_within_line"]
            except dsl.SpecError as exc:
                direction = {"undefined": str(exc)}
            row = {"official_threshold": official, "class_counts": dict(Counter(classes.values())),
                   "classes": classes,
                   "exact_run_shuffle_expectation": expected,
                   "observed_minus_expected": official["value"] - expected,
                   "shuffle_diagnostic": direction}
            print(trans, mode, official["value"], official["pass"], pairs, expected, direction, flush=True)
            report[f"{trans}:{mode}"] = row
    (WORK / "primitive-results.json").write_text(json.dumps(report, indent=2) + "\n")


if __name__ == "__main__":
    main()

