"""Independent public replication of archived #758 and primitive diagnostics."""

from collections import Counter
from fractions import Fraction
from itertools import groupby, pairwise
from math import log2
from random import Random
from pathlib import Path
import json
import re

from vs import corpus, dsl, ivtff, path

# The symbol inventory is the union of the author's listed prefix and suffix pools.
SYMBOLS = """
o a q d s t k p f c ch sh ck cth cph ok ot ol or k2 t2 p2 f2 d2 s2
ch2 sh2 ckh cth2 cfh dy dl dm ds dar dal iin in ir iir iiir al am an ar
ain aiin ey ed es edy eey eedy ly ry ny my ldy
""".split()
PATTERN = re.compile("|".join(map(re.escape, sorted(SYMBOLS, key=lambda s: (-len(s), s)))) + "|.")
MODES = ("split", "join")


def endpoints(word):
    symbols = PATTERN.findall(word)
    return symbols[0], symbols[-1]


def eligible(word):
    return len(word) > 1 and word.isalpha()


def line_index(pages):
    return {line.id: (page.id, line.words) for page in pages for line in page.lines if line.unit == "P"}


def adjacency_runs(lines, ids, loci):
    for line_id in sorted(loci):
        page, words = lines[line_id]
        if page in ids:
            for selected, stream in groupby(words, eligible):
                if selected:
                    yield list(map(endpoints, stream))


def learn(runs):
    starts, ends = marginal_counts(runs)
    return {
        symbol: (
            "start" if starts[symbol] > 2 * ends[symbol]
            else "end" if ends[symbol] > 2 * starts[symbol]
            else "ambig"
        )
        for symbol in starts.keys() | ends.keys()
    }


def marginal_counts(runs):
    starts, ends = Counter(), Counter()
    for run in runs:
        for first, last in run:
            starts[first] += 1
            ends[last] += 1
    return starts, ends


def edges(runs):
    return Counter((end, start) for run in runs for (_, end), (start, _) in pairwise(run))


def information(counts):
    outgoing = Counter()
    incoming = Counter()
    total = sum(counts.values())
    for (left, right), count in counts.items():
        outgoing[left] += count
        incoming[right] += count
    return sum(
        (count / total) * log2(count * total / (outgoing[left] * incoming[right]))
        for (left, right), count in counts.items()
    )


def is_end_start(pair, classes):
    left, right = pair
    return classes.get(left) == "end" and classes.get(right) == "start"


def exact_null_rate(runs, classes, n_pairs):
    expectation = Fraction(0)
    for run in runs:
        n_end = sum(classes.get(last) == "end" for _, last in run)
        n_start = sum(classes.get(first) == "start" for first, _ in run)
        n_both = sum(classes.get(first) == "start" and classes.get(last) == "end"
                     for first, last in run)
        # A directed slot pair samples two distinct members of the run.
        expectation += Fraction(n_end * n_start - n_both, len(run))
    return float(expectation / n_pairs)


def measure(runs, classes):
    pairs = edges(runs)
    n_pairs = sum(pairs.values())
    hits = sum(n for pair, n in pairs.items() if is_end_start(pair, classes))
    unknown = sum(n for pair, n in pairs.items() if any(symbol not in classes for symbol in pair))
    rng = Random(2711)
    mi_null = []
    rate_null = []
    for _ in range(100):
        reordered = [list(run) for run in runs]
        for run in reordered:
            rng.shuffle(run)
        null = edges(reordered)
        mi_null.append(information(null))
        rate_null.append(sum(n for pair, n in null.items() if is_end_start(pair, classes)) / n_pairs)
    return {
        "tokens": sum(map(len, runs)),
        "pairs": n_pairs,
        "hits": hits,
        "unknown_pairs": unknown,
        "rate": hits / n_pairs,
        "mi_bits": information(pairs),
        "exact_null_rate_mean": exact_null_rate(runs, classes, n_pairs),
        "null_mi_bits": sum(mi_null) / len(mi_null),
        "null_rate_mean": sum(rate_null) / len(rate_null),
        "null_rate_range": [min(rate_null), max(rate_null)],
        "upper_rate_add_one": (1 + sum(x >= hits / n_pairs for x in rate_null)) / (len(rate_null) + 1),
    }


def main():
    stock_train, stock_eval = corpus.split_pages("practice", "zl")
    train_ids = {page.id for page in stock_train}
    eval_ids = {page.id for page in stock_eval}
    views = {
        (trans, mode): ivtff.parse(path("data", "raw", corpus.TRANSLITERATIONS[trans]), uncertain_space=mode)
        for trans in corpus.EVA_TRANSLITERATIONS for mode in MODES
    }
    indexes = {view: line_index(pages) for view, pages in views.items()}
    common = set.intersection(*(set(index) for index in indexes.values()))
    classes = learn(adjacency_runs(indexes["zl", "split"], train_ids, common))
    reports = {
        "shared_loci": len(common),
        "class_totals": dict(Counter(classes.values())),
        "shared_locus_reference": {
            f"{trans}_{mode}": measure(list(adjacency_runs(index, eval_ids, common)), classes)
            for (trans, mode), index in indexes.items()
        },
        "primitive_independent_replay": {},
        "space_policy_class_changes": {},
    }
    for (trans, mode), index in indexes.items():
        pages = views[trans, mode]
        train = [page for page in pages if page.id in train_ids]
        evaluation = [page for page in pages if page.id in eval_ids]
        own_classes = learn(adjacency_runs(index, train_ids, index))
        section = measure(list(adjacency_runs(index, eval_ids, index)), own_classes)
        section["class_totals"] = dict(Counter(own_classes.values()))
        # Independently compare our measurements to the production code. The parser is shared.
        calc = dsl._boundary_classes(dsl.tokens(train))
        assert calc == own_classes, (trans, mode, {"mine": own_classes, "primitive": calc})
        val, details = dsl._boundary_class_value(dsl.tokens(evaluation), calc)
        assert val == section["rate"] and details["pairs"] == section["pairs"], (trans, mode)
        reports["primitive_independent_replay"][f"{trans}_{mode}"] = section
    for trans in corpus.EVA_TRANSLITERATIONS:
        views_of_class = {
            mode: learn(adjacency_runs(indexes[trans, mode], train_ids, indexes[trans, mode]))
            for mode in MODES
        }
        views_of_count = {
            mode: marginal_counts(adjacency_runs(indexes[trans, mode], train_ids, indexes[trans, mode]))
            for mode in MODES
        }
        first, second = (views_of_class[mode] for mode in MODES)
        joined = indexes[trans, "join"]
        joined_pairs = edges(adjacency_runs(joined, eval_ids, joined))
        reports["space_policy_class_changes"][trans] = {
            "changed_symbols": {
                symbol: {
                    mode: {"class": views_of_class[mode].get(symbol),
                           "training_initial": views_of_count[mode][0][symbol],
                           "training_final": views_of_count[mode][1][symbol]}
                    for mode in MODES
                }
                for symbol in sorted(first.keys() | second.keys())
                if first.get(symbol) != second.get(symbol)
            },
            "joined_hits_lost_by_refit": sum(
                count for pair, count in joined_pairs.items()
                if is_end_start(pair, first) and not is_end_start(pair, second)
            ),
            "joined_hits_gained_by_refit": sum(
                count for pair, count in joined_pairs.items()
                if is_end_start(pair, second) and not is_end_start(pair, first)
            ),
        }
    target = Path(__file__).with_name("independent-replay.json")
    target.write_text(json.dumps(reports, indent=2) + "\n")
    print(json.dumps(reports, indent=2))


if __name__ == "__main__":
    main()

