"""Finite-sample tails under the exact full eligible-run shuffling null."""

from collections import Counter
from functools import cache

import numpy as np

from independent_replay import MODES, adjacency_runs, edges, is_end_start, learn, line_index
from vs import corpus, ivtff, path


@cache
def sequence_counts(remaining, previous_ends):
    """Count category sequences by their number of end-to-start edges.

    Category bit 0 indicates an initial start class and bit 1 a final end
    class. With a fixed category multiset, every category sequence has the
    same number of underlying whole-word permutations.
    """
    size = sum(remaining)
    if size == 0:
        return (1,)
    answer = [0] * (size + int(previous_ends))
    for category, occurrences in enumerate(remaining):
        if occurrences == 0:
            continue
        reduced = list(remaining)
        reduced[category] -= 1
        increment = int(previous_ends and (category & 1))
        for count, frequency in enumerate(sequence_counts(tuple(reduced), bool(category & 2))):
            answer[count + increment] += frequency
    return tuple(answer)


def permutation_distribution(runs, classes):
    category_bags = Counter()
    for run in runs:
        if len(run) < 2:
            continue
        bag = Counter(
            int(classes.get(first) == "start") + 2 * int(classes.get(last) == "end")
            for first, last in run
        )
        category_bags[tuple(bag[i] for i in range(4))] += 1
    distribution = np.array([1], dtype=np.longdouble)
    for category_bag, repetitions in category_bags.items():
        frequencies = sequence_counts(category_bag, False)
        weights = np.array(frequencies, dtype=np.longdouble) / np.longdouble(sum(frequencies))
        for _ in range(repetitions):
            distribution = np.convolve(distribution, weights)
    return distribution


def main():
    training, evaluation = corpus.split_pages("practice")
    train_ids, eval_ids = ({page.id for page in pages} for pages in (training, evaluation))
    for transliteration in corpus.EVA_TRANSLITERATIONS:
        for space_policy in MODES:
            index = line_index(ivtff.parse(
                path("data", "raw", corpus.TRANSLITERATIONS[transliteration]),
                uncertain_space=space_policy,
            ))
            classes = learn(adjacency_runs(index, train_ids, index))
            runs = list(adjacency_runs(index, eval_ids, index))
            distribution = permutation_distribution(runs, classes)
            observed = sum(count for pair, count in edges(runs).items() if is_end_start(pair, classes))
            assert np.isclose(distribution.sum(), 1)
            mean = (distribution * np.arange(len(distribution))).sum()
            print(transliteration, space_policy, observed, float(mean),
                  float(distribution[observed:].sum()))


if __name__ == "__main__":
    main()
